export const SidebarProvider = cc<SidebarProviderProps>((props) => {
  const root = useSidebarRoot(props);

  return (
    <div
      data-slot="sidebar-wrapper"
      style={root.style.value}
      class={cn(
        "group/sidebar-wrapper flex min-h-svh w-full has-data-[variant=inset]:bg-sidebar",
        props.class,
      )}
      {...root.rest}
    >
      {props.children}
    </div>
  );
});

const SheetOpenSync = cc<SidebarSheetSyncProps>((props) => {
  useSidebarSheetSync(props);
  return null;
});

export type SidebarProps = JSX.IntrinsicElements["div"] & {
  side?: "left" | "right";
  variant?: "sidebar" | "floating" | "inset";
  collapsible?: "offcanvas" | "icon" | "none";
  children?: SinwanNode;
  dir?: string;
};

export const Sidebar = cc<SidebarProps>(
  ({
    side = "left",
    variant = "sidebar",
    collapsible = "offcanvas",
    class: className,
    children,
    dir,
    ...props
  }) => {
    const {
      isMobile,
      state,
      openMobile,
      setOpenMobile,
    } = useSidebar();

    if (collapsible === "none") {
      return (
        <div
          data-slot="sidebar"
          class={cn(
            "flex h-full w-(--sidebar-width) flex-col bg-sidebar text-sidebar-foreground",
            className,
          )}
          {...props}
        >
          {children}
        </div>
      );
    }

    return (
      <>
        <Show when={isMobile()}>
          <Sheet onOpenChange={setOpenMobile}>
            <SheetOpenSync
              open={openMobile.value}
            />
            <SheetContent
              dir={dir}
              data-sidebar="sidebar"
              data-slot="sidebar"
              data-mobile="true"
              class={cn(
                "w-(--sidebar-width) bg-sidebar p-0 text-sidebar-foreground [&>button]:hidden",
                className,
              )}
              style={{ "--sidebar-width": SIDEBAR_WIDTH_MOBILE }}
              side={side}
              showCloseButton={false}
            >
              <SheetHeader class="sr-only">
                <SheetTitle>Sidebar</SheetTitle>
                <SheetDescription>
                  Displays the mobile sidebar.
                </SheetDescription>
              </SheetHeader>
              <div class="flex h-full w-full flex-col">{children}</div>
            </SheetContent>
          </Sheet>
        </Show>

        <Show when={!isMobile()}>
          <div
            class="group peer hidden text-sidebar-foreground md:block"
            data-state={state()}
            data-collapsible={state() === "collapsed" ? collapsible : ""
            }
            data-variant={variant}
            data-side={side}
            data-slot="sidebar"
          >
            <div
              data-slot="sidebar-gap"
              class={cn(
                "relative w-(--sidebar-width) bg-transparent transition-[width] duration-200 ease-linear",
                "group-data-[collapsible=offcanvas]:w-0",
                "group-data-[side=right]:rotate-180",
                variant === "floating" || variant === "inset"
                  ? "group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+(--spacing(4)))]"
                  : "group-data-[collapsible=icon]:w-(--sidebar-width-icon)",
              )}
            />
            <div
              data-slot="sidebar-container"
              data-side={side}
              class={cn(
                "fixed inset-y-0 z-10 hidden h-svh w-(--sidebar-width) transition-[left,right,width] duration-200 ease-linear data-[side=left]:left-0 data-[side=left]:group-data-[collapsible=offcanvas]:left-[calc(var(--sidebar-width)*-1)] data-[side=right]:right-0 data-[side=right]:group-data-[collapsible=offcanvas]:right-[calc(var(--sidebar-width)*-1)] md:flex",
                variant === "floating" || variant === "inset"
                  ? "p-2 group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+(--spacing(4))+2px)]"
                  : "group-data-[collapsible=icon]:w-(--sidebar-width-icon) group-data-[side=left]:border-r group-data-[side=right]:border-l",
                className,
              )}
              {...props}
            >
              <div
                data-sidebar="sidebar"
                data-slot="sidebar-inner"
                class="flex size-full flex-col bg-sidebar group-data-[variant=floating]:rounded-lg group-data-[variant=floating]:shadow-sm group-data-[variant=floating]:ring-1 group-data-[variant=floating]:ring-sidebar-border"
              >
                {children}
              </div>
            </div>
          </div>
        </Show>
      </>
    );
  },
);

