      size: "default",
    },
  },
);

export type SidebarMenuButtonProps = JSX.IntrinsicElements["button"] & {
  asChild?: boolean;
  isActive?: boolean;
  tooltip?: SidebarMenuButtonTooltip;
  children?: SinwanNode;
} & VariantProps<typeof sidebarMenuButtonVariants>;

export const SidebarMenuButton = cc<SidebarMenuButtonProps>((props) => {
  const {
    asChild = false,
    isActive: _isActiveIgnored,
    variant = "default",
    size = "default",
    tooltip: _tooltip,
    class: className,
    children,
    onclick,
    ...rest
  } = props;
  const menu = useSidebarMenuButton(props);

  const shared = {
    "data-slot": "sidebar-menu-button",
    "data-sidebar": "menu-button",
    "data-size": size,
    "data-active": () => (menu.active.value ? "" : undefined),
    class: cn(sidebarMenuButtonVariants({ variant, size }), className),
    ...rest,
  };

  const button = asChild ? (
    <Slot {...shared} onclick={onclick}>
      {children}
    </Slot>
  ) : (
    <button type="button" {...shared} onclick={onclick}>
      {children}
    </button>
  );

  const tip = menu.tooltip;
  if (!tip) return button;

  return (
    <Tooltip>
      <TooltipTrigger asChild>{button}</TooltipTrigger>
      <Show when={menu.tooltipVisible.value}>
        <TooltipContent side="right" class={tip.class}>
          {tip.children}
        </TooltipContent>
      </Show>
    </Tooltip>
  );
});

